using AssetForge.Core.Models;using Microsoft.EntityFrameworkCore;namespace AssetForge.Infrastructure.Data;public class AssetForgeDbContext(DbContextOptions<AssetForgeDbContext> options):DbContext(options){public DbSet<Asset> Assets=>Set<Asset>();public DbSet<AssetCategory> Categories=>Set<AssetCategory>();public DbSet<Location> Locations=>Set<Location>();public DbSet<Department> Departments=>Set<Department>();public DbSet<AuditEvent> AuditEvents=>Set<AuditEvent>();public DbSet<Person> People=>Set<Person>();public DbSet<AssetAssignment> Assignments=>Set<AssetAssignment>();public DbSet<MaintenanceRecord> MaintenanceRecords=>Set<MaintenanceRecord>();public DbSet<Supplier> Suppliers=>Set<Supplier>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Asset>().HasIndex(x=>x.AssetTag).IsUnique();b.Entity<Asset>().Property(x=>x.PurchasePrice).HasPrecision(12,2);b.Entity<MaintenanceRecord>().Property(x=>x.Cost).HasPrecision(12,2);b.Entity<MaintenanceRecord>().HasOne(x=>x.Asset).WithMany().HasForeignKey(x=>x.AssetId).OnDelete(DeleteBehavior.Restrict);b.Entity<Asset>().HasOne(x=>x.Category).WithMany(x=>x.Assets).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);b.Entity<Asset>().HasOne(x=>x.Location).WithMany(x=>x.Assets).HasForeignKey(x=>x.LocationId).OnDelete(DeleteBehavior.SetNull);b.Entity<Asset>().HasOne(x=>x.Department).WithMany(x=>x.Assets).HasForeignKey(x=>x.DepartmentId).OnDelete(DeleteBehavior.SetNull);b.Entity<Person>().HasIndex(x=>x.Email);b.Entity<AssetAssignment>().HasOne(x=>x.Asset).WithMany().HasForeignKey(x=>x.AssetId).OnDelete(DeleteBehavior.Restrict);b.Entity<AssetAssignment>().HasOne(x=>x.Person).WithMany(x=>x.Assignments).HasForeignKey(x=>x.PersonId).OnDelete(DeleteBehavior.Restrict);}}
